/** Palettes for the old presets (material only: every other option is the original's). */
export const PALETTE_FOR = { cottage: "spruce-shingle", shop: "spruce-shingle", civic: "slate", townhouse: "dark-slate", granary: "slate", temple: "red-tile" };

export const NEW_PRESETS = {
  barn: (P) => ({
    style: "gambrel", ridgeAxis: P.wide ? "x" : "z", pitch: 1.5, upperPitch: 0.5, lower: Math.max(2, Math.round((0.4 * P.span) / 2)),
    material: "barn-red", verge: "smooth_quartz", ridge: "slab", overhang: 1, steep: true,
    dormers: { face: P.wide ? ["north", "south"] : ["east", "west"], count: P.len >= 18 ? 3 : 2, style: "gable" },
    tower: { at: [cx(P) - 1, cz(P) - 1], size: 3, height: 2, top: "lantern", material: "spruce" },
  }),
