    style: "dutch-gable", pitch: 0.67, eave: "upturned", ridge: "slab",
    material: { mix: [["deepslate_tile", 50], ["cobbled_deepslate", 30], ["polished_blackstone_brick", 20]], eave: "polished_blackstone_brick", ridge: "stone_brick", verge: "dark_oak" },   // dark-glazed with a stone-grey ridge (not quartz white) overhang: 1, steep: true,
    maxHeight: Math.max(2, Math.floor(0.6 * (P.wallH || 4))),
  }),
  "tower-cap": (P) => ({ style: "cone", pitch: 2.75, material: "slate", overhang: 1, steep: true, ...(P.span >= 7 ? { dormer: { face: P.front } } : {}) }),
  "lantern-cap": () => ({ style: "cone", pitch: 1.25, material: "red-tile", overhang: 1, ring: true, steep: true }),
  church: () => ({ style: "tiered", tiers: 3, material: { mix: [["dark_oak", 40], ["spruce", 30], ["mangrove", 15], ["cobbled_deepslate", 15]], eave: "dark_oak", ridge: "dark_oak", gradient: "none" }, pitches: [1, 1.5, 2], overhang: 1, ridgeEnds: "dragon", steep: true }),
  workshop: () => ({ style: "sawtooth", material: "copper", pitch: 1, glaze: "north", overhang: 0, steep: true }),
  desert: (P) => ({
    style: "flat-parapet", parapet: 1, material: { mix: [["smooth_sandstone", 60], ["sandstone", 25], ["mud_brick", 15]], eave: "smooth_quartz", ridge: "smooth_quartz", gradient: "none" }, trim: "smooth_quartz", overhang: 0, steep: true,
    tower: { at: [P.R[0] + 2, P.R[1] + 2], size: 3, height: 2, top: "cap", material: "smooth_sandstone", from: P.y0 + 1 },
  }),
  cafe: () => ({
    style: "flat-parapet", parapet: 0, cantilever: true, overhang: { north: 2, south: 1, east: 1, west: 1 },
    material: { mix: [["smooth_stone", 50], ["cobbled_deepslate", 25], ["polished_andesite", 25]], gradient: "none" }, trim: "smooth_quartz", fascia: "smooth_quartz", soffit: "spruce", steep: true,
  }),
};
NEW_PRESETS.pagoda = NEW_PRESETS.teahouse;
NEW_PRESETS.stave = NEW_PRESETS.church;

/** Mutate the roofs.mjs preset table: old presets get palettes, new presets are added (an old name is never replaced). */
export function applyPresets(table) {
  for (const [name, palette] of Object.entries(PALETTE_FOR)) {
    const orig = table[name];
    if (orig) table[name] = (P) => ({ ...orig(P), material: palette });
  }
  for (const [name, fn] of Object.entries(NEW_PRESETS)) if (!table[name]) table[name] = fn;
  return table;
}
