/** Garden gate: double spruce_fence_gate, x 22..23 at z 22, passage to garden. */
export const GARDEN_GATE = { x0: 22, x1: 23, y: 6, z: 22 };
/** Chimney stacks: E against the east wall x 19, S against the wing's south gable z 30. */
